const hot = name => ({src:fig(name),...images[name],layout:'stack',gutter:'auto'});
const label = (name,id) => ({id,type:'label',difficulty:'easy',points:1,prompt:'Identify the marked structures, panels or measures using the word bank.',hotspots:hot(name),wordBank:[...images[name].regions].reverse().map(x=>x.label).concat(images[name].extra),modelAnswer:images[name].regions.map(x=>`${x.label}: ${x.body}`)});
let qi=0;
function q(id,prompt,entries,modelAnswer) {
  const correct=qi++%entries.length;
  const options=entries.map(([text,feedback])=>({text,feedback}));
  options.splice(correct,0,options.shift());
  return {id,prompt,correct,options,...(modelAnswer?{modelAnswer}:{})};
}
const section=(id,title,figure,questions)=>({id,title,mode:'questions-only',...(figure?{figure:label(figure,`${id}-label`)}:{}),conceptQuiz:questions.map((x,i)=>q(`${id}-${i+1}`,...x))});

