  id:'behaviour-calc',type:'calc',difficulty:'medium',points:1,
  prompt:'Practice HW4-style subtraction: cued $300\\,\\text{ms}$, neutral $340\\,\\text{ms}$, uncued $395\\,\\text{ms}$. Compute both benefit and cost.',
  given:[{symbol:'Cued RT',value:300,unit:'ms'},{symbol:'Neutral RT',value:340,unit:'ms'},{symbol:'Uncued RT',value:395,unit:'ms'}],hints:calc.hints,
  stages:[{title:'Benefit',answer:{value:40,unit:'ms',tolerance:.1,verification:{relation:'sum',inputs:{a:.340,b:-.300},displayScale:.001}},modelAnswer:['Start from $B=RT_n-RT_v$.','Substitute $B=340-300$.','Benefit is $40\\,\\text{ms}$.']},{title:'Cost',answer:{value:55,unit:'ms',tolerance:.1,verification:{relation:'sum',inputs:{a:.395,b:-.340},displayScale:.001}},modelAnswer:['Start from $C=RT_i-RT_n$.','Substitute $C=395-340$.','Cost is $55\\,\\text{ms}$.','Check: $40+55=95\\,\\text{ms}$ equals uncued minus cued RT.']}],
  modelAnswer:['Use neutral as reference.','Benefit is $40\\,\\text{ms}$ and cost is $55\\,\\text{ms}$.']
