const lectureQuiz=[
 {id:'q01',type:'inlineChoice',difficulty:'easy',points:1,prompt:'Circle the correct alternatives.',sentences:[
  {text:'Exogenous attention is ___; endogenous attention is ___.',choices:[{options:['bottom-up','top-down'],answer:0},{options:['bottom-up','top-down'],answer:1}],explanation:'External salience captures attention; internal goals direct it.'},
  {text:'Physical conspicuity alone defines a ___ map; including goals gives a ___ map.',choices:[{options:['priority','salience'],answer:1},{options:['priority','salience'],answer:0}],explanation:'Priority combines salience and cognitive input.'}],modelAnswer:['Bottom-up is exogenous, and top-down is endogenous.','Salience reflects conspicuity; priority also incorporates goals.']},
 {id:'q02',type:'fillBlank',difficulty:'easy',points:1,prompt:'Name the source and transmitter, without a word bank.',text:'The pontine ___ releases ___ to widespread CNS targets.',blanks:[{accept:['locus coeruleus','LC','locus ceruleus']},{accept:['norepinephrine','noradrenaline']}],modelAnswer:['The locus coeruleus is the source.','Its transmitter is norepinephrine, also called noradrenaline.']},
 {...label('frontoparietal','q03'),prompt:'Identify these cortical areas in the attention network.'},
 {id:'q04',type:'interpret',difficulty:'medium',points:1,prompt:'Compare the upper and lower V4 spike traces. Which conclusion follows when the physical stimuli are identical?',
  figure:{type:'widget',name:'image-hotspots',props:{src:fig('v4'),minWidth:620,aspect:456/257,alt:'Two V4 attention conditions show the same red and green stimuli and different spike trains.',regions:[],quiz:false,layout:'stack'},caption:'V4 responses with attention directed to different locations within the receptive field.',fallbackAlt:'The upper spike train is denser than the lower train despite identical stimuli.'},
  correct:1,options:[{text:'Fewer spikes occur when the effective location is attended.',feedback:'The upper effective-attention condition has the denser spike train.'},{text:'More spikes occur when the effective location is attended.',feedback:'The upper condition shows response enhancement when attention selects the effective stimulus.'},{text:'Equal spikes occur whenever physical input stays constant.',feedback:'The traces differ despite equal input, showing attentional modulation.'}],modelAnswer:['Read the spike trains rather than just the stimulus panels.','The effective-attention condition has more spikes.','Physical input is held constant, so the response difference depends on attention.']},
 {id:'q05',type:'matchPairs',difficulty:'medium',points:1,prompt:'Match each network to the role assigned on slide 40.',right:[{id:'dan',text:'Dorsal attention network'},{id:'vis',text:'Visual-sensorimotor systems'},{id:'fp',text:'Frontoparietal task control'},{id:'co',text:'Cingulo-opercular/VAN'}],left:[{text:'Task switching and rule setting',answer:'fp',explanation:'FP establishes or switches task rules.'},{text:'Error monitoring',answer:'co',explanation:'The lecture groups CO/VAN under this role.'},{text:'Implementation of attention',answer:'dan',explanation:'DAN implements attentional selection.'},{text:'Implementation of the task',answer:'vis',explanation:'VIS-SM carries out the sensory and motor task.'}],modelAnswer:['FP: rules and switching.','CO/VAN: errors.','DAN: attention implementation.','VIS-SM: task implementation.']},
 {id:'q06',type:'classify',difficulty:'medium',points:1,prompt:'Classify each described operation by its DMN subsystem.',categories:['Core','Dorsal medial','Medial temporal'],items:[{text:'Evaluating personal information and self-related goals.',answer:'Core',explanation:'Core hubs process self-related information. The figure uses amPFC for anterior medial PFC and vmPFC for ventral medial PFC.'},{text:'Inferring another person’s beliefs or intentions.',answer:'Dorsal medial',explanation:'This subsystem supports social directed thought.'},{text:'Reconstructing a personal past event and imagining a future one.',answer:'Medial temporal',explanation:'Autobiographical memory and simulation recruit the medial temporal subsystem.'},{text:'Retrieving social semantic and abstract conceptual knowledge.',answer:'Dorsal medial',explanation:'LTC and temporal pole are dorsal medial components.'}],modelAnswer:['Personal self-processing maps to core.','Others’ minds and social knowledge map to dorsal medial.','Autobiographical past/future maps to medial temporal.']},
 {id:'q07',type:'classify',difficulty:'medium',points:1,prompt:'Assign each measurement or experimental finding to the method it describes.',categories:['fMRI','MEG','EEG'],items:[{text:'A signal increases when local oxygenated blood is oversupplied.',answer:'fMRI',explanation:'This is positive BOLD contrast.'},{text:'Net magnetic fields reflect coherent postsynaptic currents.',answer:'MEG',explanation:'MEG detects neuronal magnetic fields.'},{text:'Electric potential differences are linked to extracellular return currents.',answer:'EEG',explanation:'This is the electrical side of the source diagram.'},{text:'A slow indirect neuronal correlate has millimetre-range resolution.',answer:'fMRI',explanation:'The lecture contrasts slow BOLD and fine fMRI localization with direct MEG.'}],modelAnswer:['Oxygenation and slow haemodynamics indicate fMRI.','Magnetic fields indicate MEG.','Electric potentials indicate EEG.']},
 {id:'q08',type:'trueFalse',difficulty:'medium',points:1,prompt:'Judge each claim and correct each false statement in one line.',statements:[{text:'Default-mode regions are silent during quiet fixation.',answer:false,correction:'They show ongoing activity and correlated fluctuations during quiet fixation.'},{text:'Autobiographical past recall and future imagination can activate the DMN.',answer:true,justification:'Both tasks recruit similar PCC and mPFC regions.'},{text:'Temporal correlation alone proves a direct causal connection between two ROIs.',answer:false,correction:'Correlation suggests coordination but does not establish a direct causal connection.'},{text:'Sensorimotor, visual and default-mode network systems are described as globally segregated modules.',answer:true,justification:'The control and attention networks provide global integration.'}],modelAnswer:['Rest is active, not silent.','DMN activation can occur during autobiographical tasks.','BOLD correlation is not proof of a direct causal link.','Sensory/default modules contrast with integrating control/attention systems.']},
 {id:'q09',type:'order',difficulty:'medium',points:1,prompt:'Order the taught temporal sequence of top-down attentional modulation. Treat this as observed timing, not an exclusive causal chain.',items:['V1','LIP','Prefrontal cortex and FEF','V2','V4 and MT'],correctOrder:[2,1,4,3,0],modelAnswer:['Frontal modulation appears first.','It is followed by LIP.','Then V4/MT, V2 and V1 show modulation.','Observed timing does not establish that no parallel or recurrent influences exist.']},
 calc,
 {id:'q11',type:'groupItems',difficulty:'medium',points:1,prompt:'Sort the examples by the main source of attentional guidance.',groups:['Bottom-up','Top-down'],items:[{text:'A unique colour captures attention.',group:'Bottom-up',explanation:'Physical salience drives capture.'},{text:'A remembered page corner guides search.',group:'Top-down',explanation:'Memory and a behavioural goal guide selection.'},{text:'An unexpected flash interrupts search.',group:'Bottom-up',explanation:'The flash is an exogenous event.'},{text:'A predictive arrow directs covert attention.',group:'Top-down',explanation:'The observer uses the learned cue to direct attention.'}],modelAnswer:['Feature singletons and unexpected flashes are bottom-up.','Remembered goals and predictive central cues are top-down.']},
 {id:'q12',type:'clinicalCase',difficulty:'medium',points:1,scenario:'A patient detects visible targets and remembers the task instructions, but repeatedly fails to notice response conflicts and to adjust behaviour after errors.',prompt:'Which region’s taught role is most directly implicated?',accept:['anterior cingulate cortex','ACC','anterior cingulate'],answerLabel:'Region',modelAnswer:['The key deficit is error/conflict monitoring and feedback adjustment.','These functions are assigned to ACC on slide 45.','This is a functional implication, not a uniquely diagnostic lesion test.']},
 {id:'q13',type:'multiSelect',difficulty:'medium',points:1,prompt:'Which statements preserve the slide explanations rather than reversing them?',options:[{text:'The DMN can remain active during internally directed tasks.',correct:true,feedback:'Past/future autobiographical tasks activate DMN regions.'},{text:'The DMN becomes silent whenever any task is performed.',correct:false,feedback:'This overgeneralizes task deactivation and excludes autobiographical tasks.'},{text:'Increased deoxygenated haemoglobin strengthens the BOLD signal.',correct:false,feedback:'Deoxygenated haemoglobin causes field inhomogeneity and signal loss.'},{text:'A higher oxygenated/deoxygenated ratio strengthens BOLD.',correct:true,feedback:'The taught positive BOLD mechanism is an increased oxygenation ratio.'}],modelAnswer:['DMN activity depends on task content, not merely the presence of a task.','Positive BOLD follows increased oxygenation; deoxygenated haemoglobin produces signal loss.']},
 {id:'q14',type:'trueFalse',difficulty:'medium',points:1,prompt:'A study keeps gaze and visual input constant while moving the attentional cue. Judge the proposed conclusions and correct false ones.',statements:[{text:'A shifting retinotopic BOLD enhancement can be explained only by changed retinal input.',answer:false,correction:'Constant input and gaze leave attentional modulation as an explanation for the retinotopic shift.'},{text:'An attention-dependent V4 firing change can coexist with unchanged physical stimuli.',answer:true,justification:'Attending different stimuli within the receptive field changes their influence on firing.'},{text:'A larger BOLD response by itself identifies the exact number of extra V4 spikes.',answer:false,correction:'BOLD is an indirect population haemodynamic signal and does not specify an exact spike count.'}],modelAnswer:['First separate stimulus, gaze and attention manipulations.','The controlled input permits attention-dependent responses without a retinal change.','Then separate the methods: fMRI BOLD and V4 spikes measure different signals.','One cannot convert a BOLD amplitude directly into a precise spike count from these data.']},
 {id:'q15',type:'multiSelect',difficulty:'hard',points:1,prompt:'A goal favours a right-hand target while an irrelevant flash occurs on the left. A manipulation removes goal-related input to the priority computation but preserves visual contrast signals. Which predictions follow from the map model?',options:[{text:'Rightward goal weighting should lose its contribution.',correct:true,feedback:'Removing the cognitive input removes that source of rightward priority.'},{text:'Leftward physical salience should lose its contrast signal.',correct:false,feedback:'Physical contrast signals are explicitly preserved in this scenario.'},{text:'The flash must become the only visible item in the scene.',correct:false,feedback:'Priority selection does not imply that all other objects cease to be visible.'},{text:'The goal should still dominate with its input removed.',correct:false,feedback:'The model cannot preserve a goal contribution whose input has been removed.'}],modelAnswer:['Separate the preserved bottom-up feature contrasts from the removed top-down input.','The left flash can remain salient.','The right target loses the specified goal contribution to priority.','This does not prove that only the flash remains visible or that all other sources of relevance vanish.']},
 {id:'q16',type:'clinicalCase',difficulty:'hard',points:1,scenario:'After focal dysfunction, a participant struggles to keep a new rule in mind and manage the task. They still report errors and shift gaze normally. On difficult trials, visual selection becomes less goal-directed even though colour singletons still capture attention.',prompt:'Which taught control region best fits the combined deficit, and why can attention suffer despite preserved bottom-up capture?',accept:['dorsolateral prefrontal cortex','DLPFC','dorsolateral PFC'],answerLabel:'Region',modelAnswer:['Rule maintenance and task management point to the DLPFC role.','Maintaining a goal supports top-down input to attention-related regions.','Weaker goal support can impair priority weighting while physical salience remains available.','Preserved error detection makes ACC’s monitoring role a less direct explanation.','The scenario links taught roles; it does not establish a uniquely localizing clinical diagnosis.']},
];

